/*
 * test_framework.hpp — Minimal single-header test runner for Epilog.
 *
 * No external dependencies. Compile each test_*.cpp independently and run it.
 * A non-zero exit code means at least one test failed.
 *
 * Usage:
 *   TEST("description") { EXPECT(...); REQUIRE(...); }
 *   int main() { return epilog_test::run_all(); }
 *
 * Macros:
 *   EXPECT(expr)        — record failure if expr is false; continue test
 *   EXPECT_EQ(a, b)     — record failure if a != b; print both values
 *   EXPECT_NE(a, b)     — record failure if a == b
 *   EXPECT_NULL(p)      — record failure if p != nullptr
 *   EXPECT_NOTNULL(p)   — record failure if p == nullptr
 *   REQUIRE(expr)       — abort current test immediately if expr is false
 *   TEST(name)          — declare a test case (registers automatically)
 */

#pragma once

#include <cstdio>
#include <cstring>
#include <functional>
#include <vector>
#include <string>

namespace epilog_test {

struct Result {
    bool        passed;
    std::string name;
    std::string failure_msg;
};

struct Registry {
    struct Entry { std::string name; std::function<void()> fn; };
    std::vector<Entry>  entries;
    std::vector<Result> results;
    int                 failures = 0;

    static Registry &get() { static Registry r; return r; }

    void add(std::string name, std::function<void()> fn) {
        entries.push_back({ std::move(name), std::move(fn) });
    }
};

/* Thrown to abort a single test on REQUIRE failure. */
struct TestAbort { std::string msg; };

/* Per-test state (reset for each test). */
inline thread_local int  tl_failures    = 0;
inline thread_local bool tl_in_test     = false;

/* Record a failure inside a running test. */
inline void record_failure(const char *file, int line, const char *expr)
{
    tl_failures++;
    fprintf(stderr, "    FAIL  %s:%d  %s\n", file, line, expr);
}

inline int run_all()
{
    Registry &reg = Registry::get();
    int total   = 0;
    int passed  = 0;

    for (auto &entry : reg.entries) {
        total++;
        tl_failures = 0;
        tl_in_test  = true;
        bool aborted = false;
        std::string abort_msg;

        try {
            entry.fn();
        } catch (const TestAbort &a) {
            aborted   = true;
            abort_msg = a.msg;
            tl_failures++;
        }

        tl_in_test = false;
        bool ok = (tl_failures == 0);
        if (ok) {
            passed++;
            printf("  PASS  %s\n", entry.name.c_str());
        } else {
            printf("  FAIL  %s", entry.name.c_str());
            if (aborted) { printf("  [aborted: %s]", abort_msg.c_str()); }
            printf("\n");
        }
    }

    printf("\n%d/%d tests passed", passed, total);
    if (total - passed > 0) {
        printf("  (%d FAILED)", total - passed);
    }
    printf("\n");
    return (passed == total) ? 0 : 1;
}

/* Registration helper — instantiated by the TEST macro. */
struct Registrar {
    Registrar(const char *name, std::function<void()> fn) {
        Registry::get().add(name, std::move(fn));
    }
};

} // namespace epilog_test

/* ---- Public macros ------------------------------------------------------- */

#define TEST(name) \
    static void _test_body_##__LINE__(); \
    static ::epilog_test::Registrar _reg_##__LINE__(name, _test_body_##__LINE__); \
    static void _test_body_##__LINE__()

#define EXPECT(expr) \
    do { \
        if (!(expr)) { \
            ::epilog_test::record_failure(__FILE__, __LINE__, #expr); \
        } \
    } while (0)

#define EXPECT_EQ(a, b) \
    do { \
        auto _a = (a); auto _b = (b); \
        if (!(_a == _b)) { \
            char _buf[256]; \
            snprintf(_buf, sizeof(_buf), "%s == %s", #a, #b); \
            ::epilog_test::record_failure(__FILE__, __LINE__, _buf); \
        } \
    } while (0)

#define EXPECT_NE(a, b) \
    do { \
        auto _a = (a); auto _b = (b); \
        if (_a == _b) { \
            char _buf[256]; \
            snprintf(_buf, sizeof(_buf), "%s != %s", #a, #b); \
            ::epilog_test::record_failure(__FILE__, __LINE__, _buf); \
        } \
    } while (0)

#define EXPECT_NULL(p) \
    do { \
        if ((p) != nullptr) { \
            ::epilog_test::record_failure(__FILE__, __LINE__, #p " == nullptr"); \
        } \
    } while (0)

#define EXPECT_NOTNULL(p) \
    do { \
        if ((p) == nullptr) { \
            ::epilog_test::record_failure(__FILE__, __LINE__, #p " != nullptr"); \
        } \
    } while (0)

#define REQUIRE(expr) \
    do { \
        if (!(expr)) { \
            char _buf[256]; \
            snprintf(_buf, sizeof(_buf), "REQUIRE failed: %s", #expr); \
            throw ::epilog_test::TestAbort{ _buf }; \
        } \
    } while (0)

/*
 * test_atoms.cpp — Unit tests for the atom interning table.
 */

#include "test_framework.hpp"
#include "../include/atoms.hpp"

/* ---- Helpers ------------------------------------------------------------- */

static AtomTable make_table()
{
    AtomTable t;
    atom_table_init(&t);
    return t;
}

/* ---- Tests --------------------------------------------------------------- */

TEST("atom_table_init zeroes count")
{
    AtomTable t;
    atom_table_init(&t);
    EXPECT_EQ(atom_count(&t), 0U);
}

TEST("atom_table_init rejects null")
{
    EXPECT_EQ(atom_table_init(nullptr), -1);
}

TEST("intern returns valid id for simple atom")
{
    AtomTable t = make_table();
    AtomId id = atom_intern(&t, "alice");
    EXPECT_NE(id, ATOM_ID_INVALID);
}

TEST("intern same spelling twice returns same id")
{
    AtomTable t = make_table();
    AtomId a = atom_intern(&t, "alice");
    AtomId b = atom_intern(&t, "alice");
    EXPECT_EQ(a, b);
}

TEST("intern different spellings return different ids")
{
    AtomTable t = make_table();
    AtomId a = atom_intern(&t, "alice");
    AtomId b = atom_intern(&t, "bob");
    EXPECT_NE(a, b);
}

TEST("intern increments count")
{
    AtomTable t = make_table();
    atom_intern(&t, "alice");
    atom_intern(&t, "bob");
    atom_intern(&t, "alice"); /* duplicate — should not increment */
    EXPECT_EQ(atom_count(&t), 2U);
}

TEST("intern rejects null spelling")
{
    AtomTable t = make_table();
    EXPECT_EQ(atom_intern(&t, nullptr), ATOM_ID_INVALID);
}

TEST("intern rejects null table")
{
    EXPECT_EQ(atom_intern(nullptr, "alice"), ATOM_ID_INVALID);
}

TEST("intern rejects spelling exceeding ATOM_MAX_LEN")
{
    AtomTable t = make_table();
    char big[ATOM_MAX_LEN + 2U];
    memset(big, 'x', sizeof(big) - 1U);
    big[sizeof(big) - 1U] = '\0';
    EXPECT_EQ(atom_intern(&t, big), ATOM_ID_INVALID);
}

TEST("lookup finds interned atom")
{
    AtomTable t = make_table();
    AtomId interned = atom_intern(&t, "carol");
    AtomId found    = atom_lookup(&t, "carol");
    EXPECT_EQ(interned, found);
}

TEST("lookup returns invalid for absent atom")
{
    AtomTable t = make_table();
    EXPECT_EQ(atom_lookup(&t, "nobody"), ATOM_ID_INVALID);
}

TEST("lookup does not insert")
{
    AtomTable t = make_table();
    atom_lookup(&t, "ghost");
    EXPECT_EQ(atom_count(&t), 0U);
}

TEST("spelling round-trips through intern")
{
    AtomTable   t  = make_table();
    AtomId      id = atom_intern(&t, "hello");
    const char *sp = atom_spelling(&t, id);
    REQUIRE(sp != nullptr);
    EXPECT_EQ(strcmp(sp, "hello"), 0);
}

TEST("spelling returns null for ATOM_ID_INVALID")
{
    AtomTable t = make_table();
    EXPECT_NULL(atom_spelling(&t, ATOM_ID_INVALID));
}

TEST("spelling returns null for out-of-range id")
{
    AtomTable t = make_table();
    EXPECT_NULL(atom_spelling(&t, 9999U));
}

TEST("intern many atoms — stress collision handling")
{
    AtomTable t = make_table();
    char buf[16];
    for (uint32_t i = 0U; i < 100U; ++i) {
        snprintf(buf, sizeof(buf), "atom_%u", i);
        AtomId id = atom_intern(&t, buf);
        EXPECT_NE(id, ATOM_ID_INVALID);
    }
    EXPECT_EQ(atom_count(&t), 100U);

    /* verify all spellings still round-trip */
    for (uint32_t i = 0U; i < 100U; ++i) {
        snprintf(buf, sizeof(buf), "atom_%u", i);
        AtomId id = atom_lookup(&t, buf);
        EXPECT_NE(id, ATOM_ID_INVALID);
        const char *sp = atom_spelling(&t, id);
        REQUIRE(sp != nullptr);
        EXPECT_EQ(strcmp(sp, buf), 0);
    }
}

TEST("intern empty string is a valid atom")
{
    AtomTable t = make_table();
    AtomId id = atom_intern(&t, "");
    EXPECT_NE(id, ATOM_ID_INVALID);
    const char *sp = atom_spelling(&t, id);
    REQUIRE(sp != nullptr);
    EXPECT_EQ(strcmp(sp, ""), 0);
}

int main() { return epilog_test::run_all(); }

/*
 * test_variables.cpp — Unit tests for the variable registry.
 */

#include "test_framework.hpp"
#include "../include/variables.hpp"

static VarRegistry make_reg()
{
    VarRegistry r;
    var_registry_init(&r);
    return r;
}

TEST("var_registry_init zeroes count")
{
    VarRegistry r;
    var_registry_init(&r);
    EXPECT_EQ(var_count(&r), 0U);
}

TEST("var_registry_init rejects null")
{
    EXPECT_EQ(var_registry_init(nullptr), -1);
}

TEST("var_alloc returns valid id")
{
    VarRegistry r = make_reg();
    VarId id = var_alloc(&r, "X");
    EXPECT_NE(id, VAR_ID_INVALID);
}

TEST("var_alloc increments count")
{
    VarRegistry r = make_reg();
    var_alloc(&r, "X");
    var_alloc(&r, "Y");
    EXPECT_EQ(var_count(&r), 2U);
}

TEST("var_alloc rejects null name")
{
    VarRegistry r = make_reg();
    EXPECT_EQ(var_alloc(&r, nullptr), VAR_ID_INVALID);
}

TEST("var_alloc each call produces unique id")
{
    VarRegistry r = make_reg();
    VarId a = var_alloc(&r, "X");
    VarId b = var_alloc(&r, "X"); /* same name is allowed — fresh var */
    EXPECT_NE(a, b);
}

TEST("fresh variable walks as TERM_UNBOUND")
{
    VarRegistry r  = make_reg();
    VarId       id = var_alloc(&r, "X");
    WalkResult  wr = var_walk(&r, id);
    EXPECT_EQ(wr.tag, TERM_UNBOUND);
    EXPECT_EQ(wr.root_id, id);
}

TEST("var_bind_term stores TERM_TERMREF binding")
{
    VarRegistry r  = make_reg();
    VarId       id = var_alloc(&r, "X");
    EXPECT_EQ(var_bind_term(&r, id, 42U), 0);
    WalkResult wr = var_walk(&r, id);
    EXPECT_EQ(wr.tag, TERM_TERMREF);
    EXPECT_EQ(wr.value.term_ref, 42U);
}

TEST("var_bind_term rejects already-bound variable")
{
    VarRegistry r  = make_reg();
    VarId       id = var_alloc(&r, "X");
    var_bind_term(&r, id, 1U);
    EXPECT_EQ(var_bind_term(&r, id, 2U), -1);
}

TEST("var_bind_term rejects zero TermRef (TERM_REF_INVALID)")
{
    VarRegistry r  = make_reg();
    VarId       id = var_alloc(&r, "X");
    EXPECT_EQ(var_bind_term(&r, id, TERM_REF_INVALID), -1);
}

TEST("var_bind_var creates TERM_VAR chain")
{
    VarRegistry r = make_reg();
    VarId x = var_alloc(&r, "X");
    VarId y = var_alloc(&r, "Y");
    EXPECT_EQ(var_bind_var(&r, x, y), 0);
    WalkResult wr = var_walk(&r, x);
    EXPECT_EQ(wr.tag, TERM_UNBOUND); /* Y is also unbound, chain ends there */
    EXPECT_EQ(wr.root_id, y);
}

TEST("var_bind_var to self is a no-op")
{
    VarRegistry r  = make_reg();
    VarId       id = var_alloc(&r, "X");
    EXPECT_EQ(var_bind_var(&r, id, id), 0);
    EXPECT_EQ(var_walk(&r, id).tag, TERM_UNBOUND);
}

TEST("var_bind_atom stores TERM_ATOM binding")
{
    VarRegistry r      = make_reg();
    VarId       id     = var_alloc(&r, "X");
    const AtomId atom  = 7U;
    EXPECT_EQ(var_bind_atom(&r, id, atom), 0);
    WalkResult wr = var_walk(&r, id);
    EXPECT_EQ(wr.tag, TERM_ATOM);
    EXPECT_EQ(wr.value.atom_id, atom);
}

TEST("var_walk follows var→var chain to termref")
{
    VarRegistry r = make_reg();
    VarId x = var_alloc(&r, "X");
    VarId y = var_alloc(&r, "Y");
    var_bind_var(&r, x, y);
    var_bind_term(&r, y, 99U);
    WalkResult wr = var_walk(&r, x);
    EXPECT_EQ(wr.tag, TERM_TERMREF);
    EXPECT_EQ(wr.value.term_ref, 99U);
}

TEST("var_reset clears all bindings")
{
    VarRegistry r  = make_reg();
    VarId       id = var_alloc(&r, "X");
    var_bind_term(&r, id, 5U);
    var_reset(&r);
    EXPECT_EQ(var_count(&r), 0U);
}

TEST("var_walk on invalid id returns TERM_UNBOUND with invalid root")
{
    VarRegistry r  = make_reg();
    WalkResult  wr = var_walk(&r, VAR_ID_INVALID);
    EXPECT_EQ(wr.tag, TERM_UNBOUND);
    EXPECT_EQ(wr.root_id, VAR_ID_INVALID);
}

TEST("var_count returns 0 for null")
{
    EXPECT_EQ(var_count(nullptr), 0U);
}

int main() { return epilog_test::run_all(); }

/*
 * test_terms.cpp — Unit tests for the term arena.
 */

#include "test_framework.hpp"
#include "../include/terms.hpp"

static TermArena make_arena()
{
    TermArena a;
    term_arena_init(&a);
    return a;
}

static VarRegistry make_reg()
{
    VarRegistry r;
    var_registry_init(&r);
    return r;
}

TEST("term_arena_init zeroes count")
{
    TermArena a;
    term_arena_init(&a);
    EXPECT_EQ(a.count, 0U);
}

TEST("term_arena_init rejects null")
{
    EXPECT_EQ(term_arena_init(nullptr), -1);
}

TEST("make_atom returns valid ref")
{
    TermArena a = make_arena();
    AtomTable t; atom_table_init(&t);
    AtomId id = atom_intern(&t, "alice");
    TermRef ref = term_make_atom(&a, id);
    EXPECT_NE(ref, TERM_REF_INVALID);
}

TEST("make_atom stores TERM_KIND_ATOM")
{
    TermArena a = make_arena();
    AtomTable t; atom_table_init(&t);
    AtomId  id  = atom_intern(&t, "foo");
    TermRef ref = term_make_atom(&a, id);
    EXPECT_EQ(term_kind(&a, ref), TERM_KIND_ATOM);
}

TEST("make_atom rejects ATOM_ID_INVALID")
{
    TermArena a = make_arena();
    EXPECT_EQ(term_make_atom(&a, ATOM_ID_INVALID), TERM_REF_INVALID);
}

TEST("make_int stores TERM_KIND_INT and correct value")
{
    TermArena   a   = make_arena();
    TermRef     ref = term_make_int(&a, -42);
    REQUIRE(ref != TERM_REF_INVALID);
    const Term *t   = term_get(&a, ref);
    REQUIRE(t != nullptr);
    EXPECT_EQ(t->kind,         TERM_KIND_INT);
    EXPECT_EQ(t->data.int_val, -42);
}

TEST("make_var stores TERM_KIND_VAR and name")
{
    TermArena   a = make_arena();
    VarRegistry r = make_reg();
    VarId       v = var_alloc(&r, "MyVar");
    TermRef   ref = term_make_var(&a, v, "MyVar");
    REQUIRE(ref != TERM_REF_INVALID);
    const Term *t = term_get(&a, ref);
    REQUIRE(t != nullptr);
    EXPECT_EQ(t->kind, TERM_KIND_VAR);
    EXPECT_EQ(strcmp(t->data.var.name, "MyVar"), 0);
}

TEST("make_var stores underscore for null name")
{
    TermArena   a = make_arena();
    VarRegistry r = make_reg();
    VarId       v = var_alloc(&r, "_");
    TermRef   ref = term_make_var(&a, v, nullptr);
    REQUIRE(ref != TERM_REF_INVALID);
    const Term *t = term_get(&a, ref);
    REQUIRE(t != nullptr);
    EXPECT_EQ(t->data.var.name[0], '_');
}

TEST("make_compound stores arity and functor")
{
    TermArena a = make_arena();
    AtomTable t; atom_table_init(&t);
    AtomId f    = atom_intern(&t, "parent");
    AtomId alice = atom_intern(&t, "alice");
    AtomId bob   = atom_intern(&t, "bob");
    TermRef args[2] = { term_make_atom(&a, alice), term_make_atom(&a, bob) };
    TermRef ref = term_make_compound(&a, f, 2U, args);
    REQUIRE(ref != TERM_REF_INVALID);
    const Term *term = term_get(&a, ref);
    REQUIRE(term != nullptr);
    EXPECT_EQ(term->kind, TERM_KIND_COMPOUND);
    EXPECT_EQ(term->data.compound.arity, 2U);
    EXPECT_EQ(term->data.compound.functor, f);
}

TEST("term_arg retrieves correct argument refs")
{
    TermArena a = make_arena();
    AtomTable t; atom_table_init(&t);
    AtomId f     = atom_intern(&t, "f");
    AtomId alice = atom_intern(&t, "alice");
    AtomId bob   = atom_intern(&t, "bob");
    TermRef r0 = term_make_atom(&a, alice);
    TermRef r1 = term_make_atom(&a, bob);
    TermRef args[2] = { r0, r1 };
    TermRef comp = term_make_compound(&a, f, 2U, args);
    EXPECT_EQ(term_arg(&a, comp, 0U), r0);
    EXPECT_EQ(term_arg(&a, comp, 1U), r1);
}

TEST("term_arg returns TERM_REF_INVALID for out-of-range index")
{
    TermArena a = make_arena();
    AtomTable t; atom_table_init(&t);
    AtomId f     = atom_intern(&t, "f");
    AtomId alice = atom_intern(&t, "alice");
    TermRef args[1] = { term_make_atom(&a, alice) };
    TermRef comp = term_make_compound(&a, f, 1U, args);
    EXPECT_EQ(term_arg(&a, comp, 1U), TERM_REF_INVALID);
}

TEST("term_get returns null for TERM_REF_INVALID")
{
    TermArena a = make_arena();
    EXPECT_NULL(term_get(&a, TERM_REF_INVALID));
}

TEST("term_get returns null for out-of-range ref")
{
    TermArena a = make_arena();
    EXPECT_NULL(term_get(&a, 9999U));
}

TEST("make_compound rejects null args when arity > 0")
{
    TermArena a = make_arena();
    AtomTable t; atom_table_init(&t);
    AtomId f = atom_intern(&t, "f");
    EXPECT_EQ(term_make_compound(&a, f, 1U, nullptr), TERM_REF_INVALID);
}

TEST("multiple terms accumulate in arena with sequential refs")
{
    TermArena a = make_arena();
    AtomTable t; atom_table_init(&t);
    AtomId a1 = atom_intern(&t, "a");
    AtomId a2 = atom_intern(&t, "b");
    TermRef r1 = term_make_atom(&a, a1);
    TermRef r2 = term_make_atom(&a, a2);
    EXPECT_EQ(r2, r1 + 1U); /* refs are 1-based sequential */
    EXPECT_EQ(a.count, 2U);
}

int main() { return epilog_test::run_all(); }

/*
 * test_lexer.cpp — Unit tests for the tokenizer.
 */

#include "test_framework.hpp"
#include "../include/lexer.hpp"

static TokenList lex_str(const char *src)
{
    TokenList out;
    lex(src, &out);
    return out;
}

/* Shorthand: kind of the n-th token. */
static TokenKind kind(const TokenList &tl, uint32_t n)
{
    return tl.items[n].kind;
}

static const char *text(const TokenList &tl, uint32_t n)
{
    return tl.items[n].text;
}

/* ---- Basic token kinds --------------------------------------------------- */

TEST("lex empty string produces only EOF")
{
    TokenList tl = lex_str("");
    EXPECT_EQ(tl.count, 1U);
    EXPECT_EQ(kind(tl, 0), TOK_EOF);
}

TEST("lex atom: lowercase identifier")
{
    TokenList tl = lex_str("alice");
    REQUIRE(tl.count >= 2U);
    EXPECT_EQ(kind(tl, 0), TOK_ATOM);
    EXPECT_EQ(strcmp(text(tl, 0), "alice"), 0);
}

TEST("lex variable: uppercase initial")
{
    TokenList tl = lex_str("X");
    REQUIRE(tl.count >= 2U);
    EXPECT_EQ(kind(tl, 0), TOK_VAR);
    EXPECT_EQ(strcmp(text(tl, 0), "X"), 0);
}

TEST("lex variable: underscore initial")
{
    TokenList tl = lex_str("_Anon");
    REQUIRE(tl.count >= 2U);
    EXPECT_EQ(kind(tl, 0), TOK_VAR);
}

TEST("lex integer")
{
    TokenList tl = lex_str("42");
    REQUIRE(tl.count >= 2U);
    EXPECT_EQ(kind(tl, 0), TOK_INT);
    EXPECT_EQ(tl.items[0].int_val, 42);
}

TEST("lex single-quoted atom preserves content")
{
    TokenList tl = lex_str("'hello world'");
    REQUIRE(tl.count >= 2U);
    EXPECT_EQ(kind(tl, 0), TOK_ATOM);
    EXPECT_EQ(strcmp(text(tl, 0), "hello world"), 0);
}

TEST("lex neck operator :-")
{
    TokenList tl = lex_str(":-");
    EXPECT_EQ(kind(tl, 0), TOK_NECK);
}

TEST("lex query operator ?-")
{
    TokenList tl = lex_str("?-");
    EXPECT_EQ(kind(tl, 0), TOK_QUERY);
}

TEST("lex dot terminator")
{
    TokenList tl = lex_str("foo. ");
    /* foo, dot, EOF */
    REQUIRE(tl.count >= 3U);
    EXPECT_EQ(kind(tl, 0), TOK_ATOM);
    EXPECT_EQ(kind(tl, 1), TOK_DOT);
}

TEST("lex cut !")
{
    TokenList tl = lex_str("!");
    EXPECT_EQ(kind(tl, 0), TOK_CUT);
}

TEST("lex semicolon ;")
{
    TokenList tl = lex_str(";");
    EXPECT_EQ(kind(tl, 0), TOK_SEMI);
}

TEST("lex pipe |")
{
    TokenList tl = lex_str("|");
    EXPECT_EQ(kind(tl, 0), TOK_PIPE);
}

TEST("lex equals operator =")
{
    TokenList tl = lex_str("=");
    EXPECT_EQ(kind(tl, 0), TOK_OP);
    EXPECT_EQ(strcmp(text(tl, 0), "="), 0);
}

TEST("lex not-equals \\=")
{
    TokenList tl = lex_str("\\=");
    EXPECT_EQ(kind(tl, 0), TOK_OP);
    EXPECT_EQ(strcmp(text(tl, 0), "\\="), 0);
}

/* ---- Compound token sequences -------------------------------------------- */

TEST("lex parent(alice, bob).")
{
    TokenList tl = lex_str("parent(alice, bob).");
    /*  0:ATOM 1:LPAREN 2:ATOM 3:COMMA 4:ATOM 5:RPAREN 6:DOT 7:EOF */
    REQUIRE(tl.count >= 7U);
    EXPECT_EQ(kind(tl, 0), TOK_ATOM);
    EXPECT_EQ(kind(tl, 1), TOK_LPAREN);
    EXPECT_EQ(kind(tl, 2), TOK_ATOM);
    EXPECT_EQ(kind(tl, 3), TOK_COMMA);
    EXPECT_EQ(kind(tl, 4), TOK_ATOM);
    EXPECT_EQ(kind(tl, 5), TOK_RPAREN);
