/*
 * test_unifier.cpp — Unit tests for Robinson unification and trail.
 */

#include "test_framework.hpp"
#include "../include/unifier.hpp"

/* ---- Helpers ------------------------------------------------------------- */

struct UnifyCtx {
    AtomTable   atoms;
    TermArena   arena;
    VarRegistry vars;
    Trail       trail;

    UnifyCtx()
    {
        atom_table_init(&atoms);
        term_arena_init(&arena);
        var_registry_init(&vars);
        trail_init(&trail);
    }

    AtomId intern(const char *s) { return atom_intern(&atoms, s); }

    TermRef atom(const char *s)
    {
        return term_make_atom(&arena, atom_intern(&atoms, s));
    }

    TermRef integer(int32_t v) { return term_make_int(&arena, v); }

    TermRef var(const char *name)
    {
        VarId id = var_alloc(&vars, name);
        return term_make_var(&arena, id, name);
    }

    TermRef compound(const char *f, std::initializer_list<TermRef> args)
    {
        AtomId  fid = atom_intern(&atoms, f);
        TermRef buf[TERM_MAX_ARITY];
        uint8_t n   = 0U;
        for (TermRef r : args) { buf[n++] = r; }
        return term_make_compound(&arena, fid, n, buf);
    }

    bool unify(TermRef a, TermRef b)
    {
        return ::unify(a, b, &arena, &vars, &trail) == 1;
    }

    TermRef deref(TermRef r) { return ::deref(r, &arena, &vars); }

    uint32_t mark() { return trail_mark(&trail); }

    void undo(uint32_t m) { trail_undo(&trail, &vars, m); }
};

/* ---- Atom unification ---------------------------------------------------- */

TEST("atom unifies with itself")
{
    UnifyCtx ctx;
    TermRef a = ctx.atom("alice");
    TermRef b = ctx.atom("alice");
    EXPECT(ctx.unify(a, b));
}

TEST("different atoms fail to unify")
{
    UnifyCtx ctx;
    EXPECT(!ctx.unify(ctx.atom("alice"), ctx.atom("bob")));
}

/* ---- Integer unification ------------------------------------------------- */

TEST("equal integers unify")
{
    UnifyCtx ctx;
    EXPECT(ctx.unify(ctx.integer(42), ctx.integer(42)));
}

TEST("different integers fail to unify")
{
    UnifyCtx ctx;
    EXPECT(!ctx.unify(ctx.integer(1), ctx.integer(2)));
}

/* ---- Variable unification ------------------------------------------------ */

TEST("unbound variable unifies with atom — variable gets bound")
{
    UnifyCtx ctx;
    TermRef x    = ctx.var("X");
    TermRef alice = ctx.atom("alice");
    REQUIRE(ctx.unify(x, alice));
    TermRef dr = ctx.deref(x);
    EXPECT_EQ(dr, alice);
}

TEST("unbound variable unifies with integer")
{
    UnifyCtx ctx;
    TermRef x = ctx.var("X");
    TermRef n = ctx.integer(7);
    REQUIRE(ctx.unify(x, n));
    EXPECT_EQ(ctx.deref(x), n);
}

TEST("two unbound variables unify — one binds to the other")
{
    UnifyCtx ctx;
    TermRef x = ctx.var("X");
    TermRef y = ctx.var("Y");
    REQUIRE(ctx.unify(x, y));
    /* bind Y to an atom then deref X should reach alice */
    TermRef alice = ctx.atom("alice");
    REQUIRE(ctx.unify(y, alice));
    EXPECT_EQ(ctx.deref(x), alice);
}

TEST("variable already bound to atom — unifies with same atom")
{
    UnifyCtx ctx;
    TermRef x     = ctx.var("X");
    TermRef alice = ctx.atom("alice");
    ctx.unify(x, alice);
    EXPECT(ctx.unify(x, alice));
}

TEST("variable already bound — fails with different atom")
{
    UnifyCtx ctx;
    TermRef x = ctx.var("X");
    ctx.unify(x, ctx.atom("alice"));
    EXPECT(!ctx.unify(x, ctx.atom("bob")));
}

/* ---- Compound unification ------------------------------------------------ */

TEST("compound with same functor and arity unifies")
{
    UnifyCtx ctx;
    TermRef a = ctx.compound("f", { ctx.atom("a") });
    TermRef b = ctx.compound("f", { ctx.atom("a") });
    EXPECT(ctx.unify(a, b));
}

TEST("compound with different functor fails")
{
    UnifyCtx ctx;
    TermRef a = ctx.compound("f", { ctx.atom("a") });
    TermRef b = ctx.compound("g", { ctx.atom("a") });
    EXPECT(!ctx.unify(a, b));
}

TEST("compound with different arity fails")
{
    UnifyCtx ctx;
    TermRef a = ctx.compound("f", { ctx.atom("a") });
    TermRef b = ctx.compound("f", { ctx.atom("a"), ctx.atom("b") });
    EXPECT(!ctx.unify(a, b));
}

TEST("compound arg variables get bound")
{
    UnifyCtx ctx;
    TermRef x   = ctx.var("X");
    TermRef lhs = ctx.compound("f", { x });
    TermRef rhs = ctx.compound("f", { ctx.atom("val") });
    REQUIRE(ctx.unify(lhs, rhs));
    EXPECT_EQ(ctx.deref(x), term_arg(&ctx.arena, rhs, 0U));
}

TEST("nested compound unification")
{
    UnifyCtx ctx;
    TermRef x    = ctx.var("X");
    TermRef inner = ctx.compound("g", { x });
    TermRef lhs  = ctx.compound("f", { inner });
    TermRef rhs  = ctx.compound("f", { ctx.compound("g", { ctx.atom("z") }) });
    REQUIRE(ctx.unify(lhs, rhs));
    EXPECT_EQ(ctx.deref(x), term_arg(&ctx.arena, term_arg(&ctx.arena, rhs, 0U), 0U));
}

/* ---- Trail / backtracking ------------------------------------------------ */

TEST("trail_mark and trail_undo restore unbound state")
{
    UnifyCtx ctx;
    TermRef x     = ctx.var("X");
    uint32_t mark = ctx.mark();
    ctx.unify(x, ctx.atom("alice"));
    EXPECT_EQ(ctx.deref(x), ctx.atom("alice"));
    ctx.undo(mark);
    /* after undo, X should be unbound again */
    const Term *t = term_get(&ctx.arena, x);
    REQUIRE(t != nullptr);
    WalkResult wr = var_walk(&ctx.vars, t->data.var.var_id);
    EXPECT_EQ(wr.tag, TERM_UNBOUND);
}

TEST("trail undo does not affect bindings made before the mark")
{
    UnifyCtx ctx;
    TermRef x = ctx.var("X");
    TermRef y = ctx.var("Y");
    ctx.unify(x, ctx.atom("before"));
    uint32_t mark = ctx.mark();
    ctx.unify(y, ctx.atom("after"));
    ctx.undo(mark);
    /* X still bound */
    EXPECT_EQ(ctx.deref(x), ctx.atom("before"));
    /* Y unbound */
    const Term *ty = term_get(&ctx.arena, y);
    REQUIRE(ty != nullptr);
    EXPECT_EQ(var_walk(&ctx.vars, ty->data.var.var_id).tag, TERM_UNBOUND);
}

/* ---- Type mismatch ------------------------------------------------------- */

TEST("atom vs compound fails")
{
    UnifyCtx ctx;
    EXPECT(!ctx.unify(ctx.atom("f"), ctx.compound("f", { ctx.atom("a") })));
}

TEST("atom vs integer fails")
{
    UnifyCtx ctx;
    EXPECT(!ctx.unify(ctx.atom("a"), ctx.integer(1)));
}

int main() { return epilog_test::run_all(); }

/*
 * test_solver.cpp — Integration tests for the SLD resolution engine.
 *
 * Covers the Phase 0.1 acceptance criteria and key solver behaviours:
 * backtracking, multiple solutions, cut, built-ins.
 */

#include "test_framework.hpp"
#include "../include/solver.hpp"
#include "../include/builtins.hpp"
#include "../include/parser.hpp"
#include "../include/lexer.hpp"

/* ---- Test harness -------------------------------------------------------- */

struct SolverCtx {
    AtomTable   atoms;
    Database    db;
    TermArena   clause_arena;
    VarRegistry clause_vars;
    TermArena   query_arena;
    VarRegistry query_vars;

    SolverCtx()
    {
        atom_table_init(&atoms);
        db_init(&db);
        term_arena_init(&clause_arena);
        var_registry_init(&clause_vars);
        term_arena_init(&query_arena);
        var_registry_init(&query_vars);
    }

    /* Assert clauses from a source string. Returns number asserted or -1. */
    int load(const char *src)
    {
        static TokenList toks;
        memset(&toks, 0, sizeof(toks));
        if (lex(src, &toks) < 0) { return -1; }
        var_registry_init(&clause_vars);
        Parser p;
        if (parser_init(&p, &toks, &clause_arena, &atoms, &clause_vars) < 0) {
            return -1;
        }
        int n = 0;
        ParsedClause c;
        for (;;) {
            memset(&c, 0, sizeof(c));
            ParseResult r = parser_next_clause(&p, &c);
            if (r == PARSE_EOF) { break; }
            if (r != PARSE_OK)  { return -1; }
            if (db_assert_last(&db, &c, &clause_arena) < 0) { return -1; }
            n++;
        }
        return n;
    }

    /* Run a single query and return the solution count (0 = false). */
    uint32_t query(const char *src)
    {
        static TokenList toks;
        memset(&toks, 0, sizeof(toks));
        term_arena_init(&query_arena);
        var_registry_init(&query_vars);
        if (lex(src, &toks) < 0) { return 0; }
        Parser p;
        if (parser_init(&p, &toks, &query_arena, &atoms, &query_vars) < 0) {
            return 0;
        }
        ParsedQuery pq;
        if (parser_query(&p, &pq) != PARSE_OK) { return 0; }

        SolverEnv env;
        solver_env_init(&env, &query_arena, &clause_arena,
                        &query_vars, &clause_vars, &atoms, &db);

        return solve(&env, pq.goals, pq.goal_count,
                     [](SolverEnv *, const TermRef *, uint32_t, void *) {
                         return SOLVE_NEXT;
                     }, nullptr);
    }

    /* Run query; for first solution, invoke cb on the env to inspect bindings. */
    bool query_one(const char *src, std::function<void(SolverEnv &)> cb)
    {
        static TokenList toks;
        memset(&toks, 0, sizeof(toks));
        term_arena_init(&query_arena);
        var_registry_init(&query_vars);
        if (lex(src, &toks) < 0) { return false; }
        Parser p;
        if (parser_init(&p, &toks, &query_arena, &atoms, &query_vars) < 0) {
            return false;
        }
        ParsedQuery pq;
        if (parser_query(&p, &pq) != PARSE_OK) { return false; }

        SolverEnv env;
        solver_env_init(&env, &query_arena, &clause_arena,
                        &query_vars, &clause_vars, &atoms, &db);

        bool fired = false;
        auto wrapper_cb = [&](SolverEnv *e, const TermRef *, uint32_t, void *) {
            if (!fired) { fired = true; cb(*e); }
            return SOLVE_STOP;
        };

        solve(&env, pq.goals, pq.goal_count,
              [](SolverEnv *e, const TermRef *g, uint32_t gc, void *ud) {
                  return (*static_cast<decltype(wrapper_cb)*>(ud))(e, g, gc, nullptr);
              }, &wrapper_cb);
        return fired;
    }
};

/* ---- Phase 0.1 acceptance criteria --------------------------------------- */

TEST("0.1 acceptance: grandparent(alice, carol) succeeds")
{
    SolverCtx ctx;
    REQUIRE(ctx.load(
        "parent(alice, bob). "
        "parent(bob, carol). "
        "grandparent(X, Y) :- parent(X, Z), parent(Z, Y)."
    ) == 3);
    EXPECT_EQ(ctx.query("?- grandparent(alice, carol)."), 1U);
}

TEST("0.1 acceptance: grandparent(alice, alice) fails")
{
    SolverCtx ctx;
    REQUIRE(ctx.load(
        "parent(alice, bob). "
        "parent(bob, carol). "
        "grandparent(X, Y) :- parent(X, Z), parent(Z, Y)."
    ) > 0);
    EXPECT_EQ(ctx.query("?- grandparent(alice, alice)."), 0U);
}

/* ---- Fact queries -------------------------------------------------------- */

TEST("ground fact query succeeds")
{
    SolverCtx ctx;
    ctx.load("likes(alice, pizza).");
    EXPECT_EQ(ctx.query("?- likes(alice, pizza)."), 1U);
}

TEST("ground fact query fails for unknown fact")
{
    SolverCtx ctx;
    ctx.load("likes(alice, pizza).");
    EXPECT_EQ(ctx.query("?- likes(bob, pizza)."), 0U);
}

TEST("variable query returns all matching solutions")
{
    SolverCtx ctx;
    ctx.load("color(red). color(green). color(blue).");
    EXPECT_EQ(ctx.query("?- color(X)."), 3U);
}

/* ---- Rule chaining ------------------------------------------------------- */

TEST("single-body rule resolves correctly")
{
    SolverCtx ctx;
    ctx.load("parent(alice, bob). child(X, Y) :- parent(Y, X).");
    EXPECT_EQ(ctx.query("?- child(bob, alice)."), 1U);
}

TEST("two-body rule resolves via conjunction")
{
    SolverCtx ctx;
    ctx.load(
        "parent(alice, bob). parent(bob, carol)."
        "gp(X,Y) :- parent(X,Z), parent(Z,Y)."
    );
    EXPECT_EQ(ctx.query("?- gp(alice, carol)."), 1U);
    EXPECT_EQ(ctx.query("?- gp(alice, bob)."),   0U);
}

TEST("recursive rule — ancestor")
{
    SolverCtx ctx;
    ctx.load(
        "parent(alice, bob). parent(bob, carol). parent(carol, dave)."
        "ancestor(X,Y) :- parent(X,Y)."
        "ancestor(X,Y) :- parent(X,Z), ancestor(Z,Y)."
    );
    EXPECT_EQ(ctx.query("?- ancestor(alice, dave)."), 1U);
    EXPECT_EQ(ctx.query("?- ancestor(dave, alice)."), 0U);
}

/* ---- Backtracking -------------------------------------------------------- */

TEST("multiple clauses — correct solution count")
{
    SolverCtx ctx;
    ctx.load("fruit(apple). fruit(banana). fruit(cherry).");
    EXPECT_EQ(ctx.query("?- fruit(X)."), 3U);
}

TEST("backtracking finds second solution after first fails")
{
    SolverCtx ctx;
    ctx.load(
        "path(a, b). path(b, c). path(a, c)."
        "reachable(X, Y) :- path(X, Y)."
    );
    EXPECT_EQ(ctx.query("?- reachable(a, c)."), 1U);
}

/* ---- Built-in predicates ------------------------------------------------- */

TEST("true/0 always succeeds")
{
    SolverCtx ctx;
    EXPECT_EQ(ctx.query("?- true."), 1U);
}

TEST("fail/0 always fails")
{
    SolverCtx ctx;
    EXPECT_EQ(ctx.query("?- fail."), 0U);
}

TEST("=/2 unifies two atoms")
{
    SolverCtx ctx;
    EXPECT_EQ(ctx.query("?- foo = foo."), 1U);
}

TEST("=/2 fails for different atoms")
{
    SolverCtx ctx;
    EXPECT_EQ(ctx.query("?- foo = bar."), 0U);
}

TEST("=/2 binds variable")
{
    SolverCtx ctx;
    EXPECT_EQ(ctx.query("?- X = alice."), 1U);
}

TEST("\\=/2 succeeds for non-unifiable terms")
{
    SolverCtx ctx;
    EXPECT_EQ(ctx.query("?- foo \\= bar."), 1U);
}

TEST("\\=/2 fails for unifiable terms")
{
    SolverCtx ctx;
    EXPECT_EQ(ctx.query("?- foo \\= foo."), 0U);
}

TEST("cut stops backtracking over choice points")
{
    SolverCtx ctx;
    ctx.load("first(X) :- member(X), !. member(a). member(b). member(c).");
    /* without cut we'd get 3 solutions; with cut just 1 */
    EXPECT_EQ(ctx.query("?- first(X)."), 1U);
}

/* ---- assert / retract ---------------------------------------------------- */

TEST("assert adds fact queryable immediately")
{
    SolverCtx ctx;
    ctx.query("?- assert(dynamic(ok)).");
    EXPECT_EQ(ctx.query("?- dynamic(ok)."), 1U);
}

TEST("retract removes first matching clause")
{
    SolverCtx ctx;
    ctx.load("item(a). item(b). item(c).");
    ctx.query("?- retract(item(a)).");
    EXPECT_EQ(ctx.query("?- item(a)."), 0U);
    EXPECT_EQ(ctx.query("?- item(b)."), 1U);
}

/* ---- Conjunctive query --------------------------------------------------- */

TEST("conjunction: both goals must succeed")
{
    SolverCtx ctx;
    ctx.load("a. b.");
    EXPECT_EQ(ctx.query("?- a, b."), 1U);
}

TEST("conjunction fails if second goal fails")
{
    SolverCtx ctx;
    ctx.load("a.");
    EXPECT_EQ(ctx.query("?- a, b."), 0U);
}

int main() { return epilog_test::run_all(); }

